  "targets": {
    "generate": {
      "executor": "nx:run-commands",
      "options": {
        "commands": ["node generate.js"],
        "cwd": "packages/contracts"
      }
    },
    "test": {
      "executor": "@nx/vite:test",
      "options": {
        "config": "packages/contracts/vitest.config.ts"
      }
    }
  }
}
```

